package org.sleepwell.app;
import android.content.*;import android.database.sqlite.*;import androidx.test.platform.app.InstrumentationRegistry;import org.json.*;import org.junit.Test;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import static org.junit.Assert.*;
public final class DiaryStorageTest {
 final Context c=InstrumentationRegistry.getInstrumentation().getTargetContext();static final String TEXT="I dreamed about a quiet garden near the ocean and woke feeling calm and curious.";
 final class Fixture implements AutoCloseable{final String name="diary-"+UUID.randomUUID()+".db";final DiaryStore store=new DiaryStore(c,name);public void close(){store.close();c.deleteDatabase(name);}}
 @Test public void submittedJournalPersistsAndDuplicateOwnerCannotOverwrite()throws Exception{try(Fixture f=new Fixture()){String id=f.store.challenge("owner",TEXT,40,1000,()->true);assertEquals(id,f.store.challenge("owner",TEXT+" New words.",40,2000,()->true));assertEquals(1,f.store.count());assertEquals(TEXT,f.store.entries().get(0).text);try(DiaryStore reopened=new DiaryStore(c,f.name)){assertEquals(TEXT,reopened.entries().get(0).text);}}}
 @Test public void staleBeforeOrDuringCommitRollsBackEntry(){try(Fixture f=new Fixture()){assertThrows(IllegalStateException.class,()->f.store.challenge("owner",TEXT,40,1000,()->false));AtomicInteger checks=new AtomicInteger();assertThrows(IllegalStateException.class,()->f.store.challenge("owner",TEXT,40,1000,()->checks.incrementAndGet()==1));assertEquals(0,f.store.count());}}
 @Test public void invalidShortRepeatedOrOverlongEntryNeverCompletes(){try(Fixture f=new Fixture()){for(String bad:List.of("short","morning ".repeat(30),TEXT.repeat(100)))assertThrows(IllegalArgumentException.class,()->f.store.challenge("owner",bad,40,1000,()->true));assertEquals(0,f.store.count());}}
 @Test public void manualEditAndDeleteRequireReviewedRevision(){try(Fixture f=new Fixture()){String id=f.store.save("",0,"Dream",TEXT,1000);f.store.save(id,1000,"Edited",TEXT+" I felt rested.",2000);assertThrows(IllegalStateException.class,()->f.store.save(id,1000,"stale",TEXT,3000));assertThrows(IllegalStateException.class,()->f.store.delete(id,1000));assertEquals("Edited",f.store.entries().get(0).title);f.store.delete(id,2000);assertEquals(0,f.store.count());}}
 @Test public void exportContainsPrivateTextButNeverRuntimeOwner()throws Exception{try(Fixture f=new Fixture()){f.store.challenge("secret-run-owner",TEXT,40,1000,()->true);JSONObject exported=new JSONObject(new String(f.store.export(),java.nio.charset.StandardCharsets.UTF_8));assertEquals(1,exported.getInt("diary_format"));assertEquals(TEXT,exported.getJSONArray("entries").getJSONObject(0).getString("text"));assertFalse(exported.toString().contains("secret-run-owner"));}}
 @Test public void boundedPagesDoNotTruncateExport()throws Exception{try(Fixture f=new Fixture()){for(int n=0;n<201;n++)f.store.save("",0,"Entry "+n,TEXT,1000+n);assertEquals(200,f.store.entries().size());assertEquals(1,f.store.entries(200,200).size());assertEquals(201,new JSONObject(new String(f.store.export(),java.nio.charset.StandardCharsets.UTF_8)).getJSONArray("entries").length());}}
 @Test public void routineJsonRoundTripPreservesMirrorAndJournalMinimum()throws Exception{ChallengeRoutine r=new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Mirror text",3),new ChallengeRoutine.Task("Dream journal",1,0,MathSettings.LEGACY,null,120)));ChallengeRoutine copy=ChallengeRoutineJson.decode(ChallengeRoutineJson.encode(r));assertEquals(4,copy.units());assertEquals(120,copy.tasks.get(1).journalMinimum);for(Object invalid:List.of("80",80.5,4294967336L,41)){JSONObject bad=new JSONObject().put("type","Dream journal").put("rounds",1).put("minimum",invalid);assertThrows(JSONException.class,()->ChallengeRoutineJson.decode(new JSONArray().put(bad)));}}
 @Test public void journalDatabaseNeverChangesOriginalSleepRowsOrPreferences()throws Exception{String fingerprint;try(Store original=new Store(c)){fingerprint=BackupFingerprint.read(original);}Map<String,?> preferences=new HashMap<>(Prefs.of(c).getAll());try(Fixture f=new Fixture()){String id=f.store.challenge("owner",TEXT,40,1000,()->true);f.store.save(id,1000,"Personal edited dream",TEXT,2000);f.store.delete(id,2000);}try(Store original=new Store(c)){assertEquals(fingerprint,BackupFingerprint.read(original));}assertEquals(preferences,Prefs.of(c).getAll());}
 @Test public void manualCreateRequestIsIdempotentAfterAmbiguousCompletion(){try(Fixture f=new Fixture()){String request=UUID.randomUUID().toString();assertEquals(request,f.store.save(request,0,"Dream",TEXT,1000));assertEquals(request,f.store.save(request,0,"Dream",TEXT,2000));assertEquals(1,f.store.count());assertEquals(1000,f.store.entries().get(0).updated);assertThrows(IllegalStateException.class,()->f.store.save(request,0,"Changed",TEXT,3000));assertEquals("Dream",f.store.entries().get(0).title);}}
 @Test public void failedDatabaseInsertCannotProduceJournalCompletion(){try(Fixture f=new Fixture()){f.store.getWritableDatabase().execSQL("CREATE TRIGGER fail_diary BEFORE INSERT ON entries BEGIN SELECT RAISE(ABORT,'Injected diary failure'); END");assertThrows(SQLiteException.class,()->f.store.challenge("owner",TEXT,40,1000,()->true));assertEquals(0,f.store.count());}}
}
